
 'use client';
 
import axios from 'axios';
import axios from 'axios';
 
 interface User {
   id: string;
   name: string;
   role: 'admin' | 'driver';
 }
 
 interface AuthContextType {
  login: (username: string, password: string) => Promise<void>;
  login: (username: string, password: string) => Promise<void>;
   logout: () => void;
   loading: boolean;
 }
 
 const AuthContext = createContext<AuthContextType | undefined>(undefined);
export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    const checkAuth = async () => {
      try {
        // Mock auth check for testing
        const mockUser: User = { id: 'admin-1', name: 'مدیر سیستم', role: 'admin' };
        setUser(mockUser);
        setLoading(false);
      } catch (error) {
        console.error('Auth check failed:', error);
        setLoading(false);
      }
    };
 
    checkAuth();
  }, []);
 
  const login = async (username: string, password: string) => {
    try {
      // Mock login for testing
      if ((username === 'admin' && password === 'admin123') || (username === 'driver' && password === 'driver123')) {
        const mockUser: User = username === 'admin' ? 
          { id: 'admin-1', name: 'مدیر سیستم', role: 'admin' } :
          { id: 'driver-1', name: 'راننده', role: 'driver' };
        setUser(mockUser);
      } else {
        throw new Error('Invalid credentials');
      }
    } catch (error) {
      console.error('Login failed:', error);
      throw error;
    }
  };
 
  const logout = async () => {
    try {
      // Mock logout
      setUser(null);
    } catch (error) {
      console.error('Logout failed:', error);
    }
  };
 
  return (
    <AuthContext.Provider value={{ user, login, logout, loading }}>
      {children}
    </AuthContext.Provider>
  );
};
 
export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};
